#!/usr/bin/env node
/*
 * Extract Part B of REVIEW_CHECKLIST.md into JSON for verification work.
 *
 * REVIEW_CHECKLIST.md is generated by build-review-checklist.js, so it is
 * always in sync with the data — but it is markdown, and markdown is not a
 * convenient thing to work 571 claims against. This reads it back into a
 * structure that can be classified, deduplicated and ticked off.
 *
 * Usage:
 *   node extract-partb.js <REVIEW_CHECKLIST.md> <out.json>
 *
 * Output: [{std, lesson, where, claim}] — one row per claim, in file order.
 * Also prints the assertion/pointer split, because an assertion ("IPC-A-610
 * Class 3 requires 75 % fill") states what a standard says and must be read
 * against the standard, while a pointer ("verify against IPC-A-610") only
 * asserts that the document is the right one to check.
 */
'use strict';
var fs = require('fs');

var md = process.argv[2];
var out = process.argv[3];
if (!md || !out) { console.error('usage: node extract-partb.js <checklist.md> <out.json>'); process.exit(2); }

var lines = fs.readFileSync(md, 'utf8').split('\n');
var rows = [];
var std = null;
var inTbl = false;

lines.forEach(function (l) {
  var h = /^### (.+?) — (\d+) claims$/.exec(l);
  if (h) { std = h[1]; inTbl = false; return; }
  if (/^\| Lesson \| Where \| Claim/.test(l)) { inTbl = true; return; }
  if (/^## /.test(l)) { inTbl = false; return; }
  if (!inTbl || !std || l.charAt(0) !== '|') return;
  if (/^\|\s*---/.test(l)) return;
  var m = /^\| ([^|]+) \| `([^`]+)` \| ([^|]*) \| [^|]* \|$/.exec(l);
  if (m) rows.push({ std: std, lesson: m[1].trim(), where: m[2], claim: m[3].trim() });
});

fs.writeFileSync(out, JSON.stringify(rows, null, 1));

var ASSERT = /\b(shall|must|requires?|specifies?|defines?|gives?|states?|is set|limit(?:s|ed)?\s+(?:at|to)|minimum of|maximum of|no more than|not exceed|at least|tolerance of|class \d[^,.]{0,25}(?:requires|minimum|maximum)|per\s+(IPC|J-STD|ISO|IEC|ANSI|UL))/i;
var POINTER = /(verify|check|confirm|validate|review|assess|consult|refer|compare|cross-check|reconcile)[^.]{0,40}(against|with|per|to|using|in)\s+(your|the\s+)?(IPC|J-STD|ISO|IEC|ANSI|UL|ESD|contract|drawing|datasheet|requirement)/i;

var assertions = rows.filter(function (r) { return ASSERT.test(r.claim); });
var pointers = rows.filter(function (r) { return POINTER.test(r.claim) && !ASSERT.test(r.claim); });

console.log('extract-partb: ' + rows.length + ' claims, ' + assertions.length +
  ' assertions, ' + pointers.length + ' pointers, ' +
  (rows.length - assertions.length - pointers.length) + ' other');

function norm(s) {
  return s.toLowerCase().replace(/[^a-z0-9%.°µ]/g, ' ').replace(/\s+/g, ' ').trim();
}
var g = {};
assertions.forEach(function (r) { var k = norm(r.claim); (g[k] = g[k] || []).push(r); });
var keys = Object.keys(g);
var dedup = keys.map(function (k) {
  return {
    std: g[k][0].std, claim: g[k][0].claim, n: g[k].length,
    where: g[k].map(function (r) { return r.lesson + ' ' + r.where; })
  };
});
dedup.sort(function (a, b) { return b.n - a.n; });
fs.writeFileSync(out.replace(/\.json$/, '-dedup.json'), JSON.stringify(dedup, null, 1));

console.log('  distinct assertion texts: ' + keys.length +
  ' (' + keys.filter(function (k) { return g[k].length > 1; }).length + ' repeated)');

var by = {};
dedup.forEach(function (r) { by[r.std] = (by[r.std] || 0) + 1; });
Object.keys(by).sort(function (a, b) { return by[b] - by[a]; }).forEach(function (k) {
  console.log('    ' + k + ': ' + by[k]);
});
